"""The bootstrap that every generated Kaggle kernel runs.

The rendered script is self-contained: it unpacks the embedded ``magpie``
bundle onto ``sys.path``, imports the job's entrypoint and calls
``entrypoint(config, out_dir)``. It never lets a job exception fail the
kernel: errors are written to ``out/_status.json`` so the runner can always
pull back logs and partial results.
"""

from __future__ import annotations

import json

TEMPLATE = '''\
# Magpie kernel "{name}" - generated by magpie.runners.kaggle; do not edit by hand.
# git {git_sha}{dirty_tag} | bundle sha256 {bundle_sha256}
import base64, importlib, io, json, os, sys, time, traceback, zipfile
from pathlib import Path

BUNDLE_B64 = "{bundle_b64}"
BUNDLE_SHA256 = "{bundle_sha256}"
JOB = json.loads({job_json!r})
OUT = Path(JOB.get("out_dir", "/kaggle/working/out"))
SRC = Path("/tmp/magpie_src")


def _unpack():
    import hashlib
    raw = base64.b64decode(BUNDLE_B64)
    got = hashlib.sha256(raw).hexdigest()
    if got != BUNDLE_SHA256:
        raise RuntimeError("bundle hash mismatch: " + got)
    SRC.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as zf:
        zf.extractall(SRC)
    sys.path.insert(0, str(SRC))
    os.environ["PYTHONPATH"] = str(SRC) + os.pathsep + os.environ.get("PYTHONPATH", "")
    os.environ["MAGPIE_GIT_SHA"] = JOB["git_sha"]
    os.environ["MAGPIE_GIT_DIRTY"] = "1" if JOB["git_dirty"] else "0"
    os.environ.setdefault("HF_HOME", "/tmp/hf")  # keep caches out of the outputs


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    t0 = time.time()
    status = {{"job": JOB["name"], "git_sha": JOB["git_sha"], "git_dirty": JOB["git_dirty"],
              "bundle_sha256": BUNDLE_SHA256, "started_unix": t0, "ok": False}}
    try:
        _unpack()
        module, func = JOB["entrypoint"].split(":")
        getattr(importlib.import_module(module), func)(JOB["config"], OUT)
        status["ok"] = True
    except BaseException:
        status["error"] = traceback.format_exc()
        print(status["error"], file=sys.stderr, flush=True)
    finally:
        status["elapsed_s"] = round(time.time() - t0, 1)
        (OUT / "_status.json").write_text(json.dumps(status, indent=2))
        print("MAGPIE_STATUS " + json.dumps({{k: status[k] for k in ("job", "ok", "elapsed_s")}}),
              flush=True)


main()
'''


def render_kernel(
    *, name: str, entrypoint: str, config: dict, bundle_b64: str, bundle_sha256: str,
    git_sha: str, git_dirty: bool, out_dir: str = "/kaggle/working/out",
) -> str:
    """Render a runnable kernel script for ``entrypoint(config, out_dir)``."""
    job = {"name": name, "entrypoint": entrypoint, "config": config, "git_sha": git_sha,
           "git_dirty": git_dirty, "out_dir": out_dir}
    return TEMPLATE.format(
        name=name,
        git_sha=git_sha,
        dirty_tag=" (dirty)" if git_dirty else "",
        bundle_b64=bundle_b64,
        bundle_sha256=bundle_sha256,
        job_json=json.dumps(job, sort_keys=True),
    )
